-- BLINDSPOT-2 (follow-up to 2026-11-04-blind-spot-audit.sql; 2026-11-04, charter pillar: autonomy; cost pillar: SQL only, zero AI calls). Owner: "What are you missing? ... ALWAYS AND AUTOMATICALLY".
-- Hourly :55 workflow reads the existing ledgers and files at most one deduped BLINDSPOT-1 issue per blind spot, each with a closing condition:
--   beliefs whose latest probe fails (live data contradicts them), beliefs untested for 48 h, failure modes whose detector never ran or has no active contract, metrics not refreshed for 3 days, merged code tasks with no deploy evidence; it also re-arms any active contract parked more than 3 hours beyond its cadence, reports migration files with a failed run and no later ok run, and reports contracts that stay parked (22 belief contracts were due 60 hours out on 2026-11-04 at a 1 hour cadence).
-- Reuses belief_registry, failure_modes, remediation_contracts, metric_registry; duplicates no existing fm-* detector (fm-open-loops-unclosed keeps the unclosed-issue check). Adds no gate and no owner card.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE fleet_crons SET enabled = 0 WHERE name = 'blind-spot-audit-hourly'; UPDATE fleet_tasks SET enabled = 0 WHERE id = 'blind-spot-audit'; UPDATE metric_registry SET state = 'RETIRED' WHERE metric = 'blindspots_open';

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('blind-spot-audit', 'BLINDSPOT-1: hourly audit of beliefs, detectors and metrics nobody reads (SQL only)', 'workflow', '{"steps":[{"type":"sql","name":"belief-contradicted","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''BLINDSPOT-1: belief '' || b.belief_key || '' is contradicted by its live probe'', ''Belief \"'' || b.claim || ''\" (confidence '' || b.confidence || '') failed its latest probe '' || b.probe_class || ''. Fix the system so the claim is true, or lower the belief with evidence in belief_registry. Closes when the latest remediation_verifications row for the class passes.'', ''blind-spot-audit'', ''structure'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM belief_registry b WHERE (SELECT v.pass FROM remediation_verifications v WHERE v.class = b.probe_class ORDER BY v.id DESC LIMIT 1) = 0 AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title = ''BLINDSPOT-1: belief '' || b.belief_key || '' is contradicted by its live probe'') LIMIT 3"},{"type":"sql","name":"belief-unprobed","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''BLINDSPOT-1: belief '' || b.belief_key || '' has no probe result in 48 hours'', ''Belief probe '' || b.probe_class || '' last ran '' || COALESCE((SELECT MAX(v.verified_at) FROM remediation_verifications v WHERE v.class = b.probe_class), ''never'') || ''. A belief nobody tests is a guess. Give it a running d1-query contract (remediation_contracts class = probe_class, status active). Closes when a verification row is under 48 hours old.'', ''blind-spot-audit'', ''structure'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM belief_registry b WHERE COALESCE((SELECT MAX(v.verified_at) FROM remediation_verifications v WHERE v.class = b.probe_class), '''') < datetime(''now'', ''-48 hours'') AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title = ''BLINDSPOT-1: belief '' || b.belief_key || '' has no probe result in 48 hours'') LIMIT 3"},{"type":"sql","name":"fm-never-probed","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''BLINDSPOT-1: '' || n || '' failure modes have a detector that never ran'', n || '' failure_modes rows have no remediation_verifications row for their probe_class, or no active remediation_contracts row. Example: '' || ex || ''. A failure mode without a running detector is not covered. Give each an active d1-query contract. Closes when this count is 0.'', ''blind-spot-audit'', ''structure'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM (SELECT COUNT(*) n, MIN(f.fm_key) ex FROM failure_modes f WHERE f.probe_class IS NOT NULL AND (NOT EXISTS (SELECT 1 FROM remediation_verifications v WHERE v.class = f.probe_class) OR NOT EXISTS (SELECT 1 FROM remediation_contracts c WHERE c.class = f.probe_class AND c.status = ''active''))) x WHERE n > 0 AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''BLINDSPOT-1: % failure modes have a detector that never ran'')"},{"type":"sql","name":"metrics-stale","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''BLINDSPOT-1: '' || n || '' metrics have not refreshed in 3 days'', n || '' metric_registry rows are stale or never measured. Example: '' || ex || ''. A metric nobody refreshes is read by nobody. Refresh it, or retire it by migration with its rollback. Closes when this count is 0.'', ''blind-spot-audit'', ''structure'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM (SELECT COUNT(*) n, MIN(metric) ex FROM metric_registry WHERE COALESCE(state, '''') <> ''RETIRED'' AND (last_refreshed IS NULL OR last_refreshed < strftime(''%Y-%m-%dT%H:%M:%SZ'', ''now'', ''-3 days''))) x WHERE n > 0 AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''BLINDSPOT-1: % metrics have not refreshed in 3 days'')"},{"type":"sql","name":"rearm-parked","db":"AUDIT","sql":"UPDATE remediation_contracts SET next_due_at = datetime(''now''), status = ''active'' WHERE status = ''active'' AND next_due_at > datetime(''now'', ''+'' || (COALESCE(expected_cadence_h, 1) + 3) || '' hours'') AND class NOT LIKE ''goal-%''"},{"type":"sql","name":"merged-no-deploy","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''BLINDSPOT-1: '' || n || '' merged code tasks have no deploy evidence after 2 hours'', n || '' code_tasks merged in the last 7 days have deployed_at NULL more than 2 hours after merge. Oldest: '' || oldest || ''. A merge without a recorded live deploy is a claim nobody verified. Redeploy through the canonical path and record deployed_at (DEPLOY-ALL-MERGES-1), or record why the task changed no worker. Closes when this count is 0.'', ''blind-spot-audit'', ''structure'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM (SELECT COUNT(*) n, MIN(merged_at) oldest FROM code_tasks WHERE merged_at > datetime(''now'', ''-7 days'') AND merged_at < datetime(''now'', ''-2 hours'') AND deployed_at IS NULL) x WHERE n > 0 AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''BLINDSPOT-1: % merged code tasks have no deploy evidence after 2 hours'')"},{"type":"sql","name":"migration-unapplied","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''BLINDSPOT-1: '' || n || '' migration files have no ok row in migration_runs'', n || '' files in migration_runs have a failed run and no later ok run. Example: '' || ex || '' ('' || COALESCE(err, '''') || ''). A merged migration that never applied means the live system differs from main. Fix the file with a later migration, or record why it is superseded. Closes when this count is 0.'', ''blind-spot-audit'', ''structure'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM (SELECT COUNT(*) n, MIN(file) ex, MIN(substr(error, 1, 120)) err FROM migration_runs r WHERE status <> ''ok'' AND NOT EXISTS (SELECT 1 FROM migration_runs o WHERE o.file = r.file AND o.status = ''ok'' AND o.id > r.id)) x WHERE n > 0 AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''BLINDSPOT-1: % migration files have no ok row in migration_runs'')"},{"type":"sql","name":"contracts-parked","db":"AUDIT","sql":"INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at) SELECT ''BLINDSPOT-1: '' || n || '' active contracts are parked past their cadence'', n || '' active remediation_contracts have next_due_at more than 3 hours beyond their cadence after the re-arm step. Example: '' || ex || ''. Something re-parks them; find the writer of next_due_at. Closes when this count is 0.'', ''blind-spot-audit'', ''structure'', ''medium'', ''open'', CAST(strftime(''%s'',''now'') AS INTEGER), CAST(strftime(''%s'',''now'') AS INTEGER) FROM (SELECT COUNT(*) n, MIN(class) ex FROM remediation_contracts WHERE status = ''active'' AND next_due_at > datetime(''now'', ''+'' || (COALESCE(expected_cadence_h, 1) + 3) || '' hours'') AND class NOT LIKE ''goal-%'') x WHERE n > 0 AND NOT EXISTS (SELECT 1 FROM agent_issues a WHERE a.status = ''open'' AND a.title LIKE ''BLINDSPOT-1: % active contracts are parked past their cadence'')"},{"type":"sql","name":"metric","db":"AUDIT","sql":"UPDATE metric_registry SET last_value = CAST((SELECT COUNT(*) FROM agent_issues WHERE status = ''open'' AND title LIKE ''BLINDSPOT-1:%'') AS TEXT), last_refreshed = strftime(''%Y-%m-%dT%H:%M:%SZ'',''now''), state = ''MEASURED'' WHERE metric = ''blindspots_open''"}]}', 60000, 1, 1, 1, strftime('%Y-%m-%dT%H:%M:%SZ','now'));

INSERT OR REPLACE INTO fleet_crons (name, cron_expr, task_id, enabled, timezone, updated_at)
VALUES ('blind-spot-audit-hourly', '55 * * * *', 'blind-spot-audit', 1, 'UTC', strftime('%Y-%m-%dT%H:%M:%SZ','now'));

-- CAUSE-MAPPED: informational count of open BLINDSPOT-1 issues; the issues themselves carry the lever, so the metric has no trigger.
INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, target, owner, disposition_actor, refresh_cadence, state, last_value, last_refreshed)
VALUES ('blindspots_open', 'operational', 'target', 'open agent_issues titled BLINDSPOT-1:%', 'qnfo-audit.agent_issues (BLINDSPOT-1)', '0', 'qnfo-fleet-control', 'agent:blind-spot-audit', 'hourly', 'MEASURED', NULL, NULL);
